UPDATE notices
SET view_count = view_count + 1
WHERE id = #{id}

mapper.select:
SELECT id, title, content, user_id as userId, category, is_important as isImportant, is_popup as isPopup, DATE_FORMAT(publish_date, '%Y-%m-%d %H:%i:%s') as publishDate, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') as createdAt, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') as updatedAt, view_count as viewCount FROM notices
AND (title LIKE CONCAT('%', #{search}, '%') OR content LIKE CONCAT('%', #{search}, '%'))
AND category = #{category}
AND is_important = #{isImportant}
ORDER BY is_important DESC, publish_date DESC LIMIT #{limit} OFFSET #{offset}

